        _updateBriefing(state) {
            var period = state.currentPeriod || 1;

            var r1 = document.getElementById('round1Panel');
            var r2 = document.getElementById('round2Panel');
            var r3 = document.getElementById('round3Panel');

            if (r1) r1.style.display = period === 1 ? 'block' : 'none';
            if (r2) r2.style.display = period === 2 ? 'block' : 'none';
            if (r3) r3.style.display = period === 3 ? 'block' : 'none';

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                if (period === 1) briefEl.innerHTML = window.mySimulation.t('r1_briefing');
                else if (period === 2) briefEl.innerHTML = window.mySimulation.t('r2_briefing');
                else if (period === 3) briefEl.innerHTML = window.mySimulation.t('r3_briefing');
            }

            var phaseEl = document.getElementById('phaseDisplay');
            if (phaseEl) {
                if (period === 1) phaseEl.textContent = window.mySimulation.t('r1_phase_name');
                else if (period === 2) phaseEl.textContent = window.mySimulation.t('r2_phase_name');
                else if (period === 3) phaseEl.textContent = window.mySimulation.t('r3_phase_name');
            }
        }
    }

    document.addEventListener('DOMContentLoaded', () => {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new EntrevistaAdapter(), {
            simulationType: 'mi_primera_entrevista',
            maxPeriods: 3,
            autoSaveInterval: 30000
        });
